//! Checks every runtime helper against golden tables produced by V8.
//!
//! The tables in `tests/golden/*.txt` are generated by `tests/golden/generate.mjs` (run it
//! with Node and commit the result). Every helper must match bit for bit (any NaN matches any
//! NaN, since JavaScript cannot tell NaNs apart), except the transcendental functions, which
//! come from `libm` instead of V8's fdlibm port: those must stay within [`MAX_ULPS`], and the
//! ones listed in [`EXACT_TRANSCENDENTALS`] must match exactly.

use std::path::Path;

use trioxide_rt::{
    array::{self, Element, U8Clamped},
    conv, math, ops,
};

/// The largest difference allowed between `libm` and V8, in units in the last place.
const MAX_ULPS: u64 = 2;

/// Transcendental functions that matched V8 exactly on every input in the tables. The others
/// (`sin`, `cos`, `cosh`, `tanh`, `asinh`, `acosh`, `exp`, `log`, `log10`, `cbrt`, `pow`)
/// differ on some inputs; `docs/ABI.md` ("Numerics") documents this.
const EXACT_TRANSCENDENTALS: &[&str] = &[
    "tan", "asin", "acos", "atan", "atan2", "sinh", "atanh", "expm1", "log1p", "log2",
];

fn parse(token: &str) -> f64 {
    token
        .parse()
        .unwrap_or_else(|_| panic!("bad number {token:?}"))
}

fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits() || (a.is_nan() && b.is_nan())
}

fn ulps(a: f64, b: f64) -> u64 {
    if same(a, b) {
        return 0;
    }
    if a.is_nan() || b.is_nan() || a.is_sign_negative() != b.is_sign_negative() {
        return u64::MAX;
    }
    a.to_bits().abs_diff(b.to_bits())
}

fn bool_f64(b: bool) -> f64 {
    conv::bool_to_f64(b)
}

#[expect(
    clippy::cast_possible_truncation,
    reason = "the tables hold int32 operands"
)]
fn int(x: f64) -> i32 {
    x as i32
}

fn store<T: Element>(x: f64) -> f64 {
    T::from_f64(x).to_f64()
}

/// The runtime's answer for a table row.
fn evaluate(name: &str, args: &[f64]) -> f64 {
    let a = args[0];
    let b = args.get(1).copied().unwrap_or(f64::NAN);
    let c = args.get(2).copied().unwrap_or(f64::NAN);
    match name {
        "round" => math::round(a),
        "sign" => math::sign(a),
        "trunc" => math::trunc(a),
        "floor" => math::floor(a),
        "ceil" => math::ceil(a),
        "abs" => math::abs(a),
        "sqrt" => math::sqrt(a),
        "fround" => math::fround(a),
        "clz32" => f64::from(math::clz32(a)),
        "to_int32" => f64::from(conv::to_int32(a)),
        "to_uint32" => f64::from(conv::to_uint32(a)),
        "bit_not" => f64::from(ops::bit_not(a)),
        "to_boolean" => bool_f64(conv::to_boolean(a)),
        "neg" => -a,
        "store_i8" => store::<i8>(a),
        "store_u8" => store::<u8>(a),
        "store_u8_clamped" => store::<U8Clamped>(a),
        "store_i16" => store::<i16>(a),
        "store_u16" => store::<u16>(a),
        "store_i32" => store::<i32>(a),
        "store_u32" => store::<u32>(a),
        "store_f32" => store::<f32>(a),
        "store_f64" => store::<f64>(a),

        "max" => math::max(a, b),
        "min" => math::min(a, b),
        "imul" => f64::from(math::imul(a, b)),
        "hypot2" => math::hypot2(a, b),
        "add" => a + b,
        "sub" => a - b,
        "mul" => a * b,
        "div" => a / b,
        "rem" => ops::rem(a, b),
        "bit_and" => f64::from(ops::bit_and(a, b)),
        "bit_or" => f64::from(ops::bit_or(a, b)),
        "bit_xor" => f64::from(ops::bit_xor(a, b)),
        "shl" => f64::from(ops::shl(a, b)),
        "shr" => f64::from(ops::shr(a, b)),
        "ushr" => f64::from(ops::ushr(a, b)),
        "lt" => bool_f64(a < b),
        "le" => bool_f64(a <= b),
        "gt" => bool_f64(a > b),
        "ge" => bool_f64(a >= b),
        #[expect(clippy::float_cmp, reason = "testing JS `===`")]
        "eq" => bool_f64(a == b),
        #[expect(clippy::float_cmp, reason = "testing JS `!==`")]
        "ne" => bool_f64(a != b),
        #[expect(clippy::neg_cmp_op_on_partial_ord, reason = "testing NaN semantics")]
        "not_lt" => bool_f64(!(a < b)),

        "hypot3" => math::hypot3(a, b, c),
        "max3" => math::max(math::max(a, b), c),
        "min3" => math::min(math::min(a, b), c),

        "rem_i32" => ops::rem_i32(int(a), int(b)),
        "div_trunc_i32" => f64::from(ops::div_trunc_i32(int(a), int(b))),
        "imul_i32" => f64::from(math::imul_i32(int(a), int(b))),
        "shl_i32" => f64::from(ops::shl_i32(int(a), int(b))),
        "shr_i32" => f64::from(ops::shr_i32(int(a), int(b))),
        "ushr_i32" => f64::from(ops::ushr_i32(int(a), int(b))),

        "get" | "get_number_array" => array::get(&[10.5, -20.0, 30.0, 40.0], a),

        "sin" => math::sin(a),
        "cos" => math::cos(a),
        "tan" => math::tan(a),
        "asin" => math::asin(a),
        "acos" => math::acos(a),
        "atan" => math::atan(a),
        "sinh" => math::sinh(a),
        "cosh" => math::cosh(a),
        "tanh" => math::tanh(a),
        "asinh" => math::asinh(a),
        "acosh" => math::acosh(a),
        "atanh" => math::atanh(a),
        "exp" => math::exp(a),
        "expm1" => math::expm1(a),
        "log" => math::log(a),
        "log1p" => math::log1p(a),
        "log2" => math::log2(a),
        "log10" => math::log10(a),
        "cbrt" => math::cbrt(a),
        "atan2" => math::atan2(a, b),
        "pow" => math::pow(a, b),
        _ => panic!("no helper for golden function {name:?}"),
    }
}

struct Row {
    line: usize,
    name: String,
    args: Vec<f64>,
    expected: f64,
}

fn rows(file: &str) -> Vec<Row> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden")
        .join(file);
    let text = std::fs::read_to_string(&path).unwrap();
    let rows: Vec<Row> = text
        .lines()
        .enumerate()
        .filter(|(_, line)| !line.is_empty() && !line.starts_with('#'))
        .map(|(index, line)| {
            let mut tokens = line.split(' ');
            let name = tokens.next().unwrap().to_string();
            let mut numbers: Vec<f64> = tokens.map(parse).collect();
            let expected = numbers.pop().unwrap();
            Row {
                line: index + 1,
                name,
                args: numbers,
                expected,
            }
        })
        .collect();
    assert!(rows.len() > 100, "{file} looks truncated");
    rows
}

fn check_exact(file: &str) {
    let mut failures = Vec::new();
    for row in rows(file) {
        let actual = evaluate(&row.name, &row.args);
        if !same(actual, row.expected) {
            failures.push(format!(
                "{file}:{}: {}({:?}) = {actual:?}, V8 says {:?}",
                row.line, row.name, row.args, row.expected
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures[..failures.len().min(40)].join("\n")
    );
}

#[test]
fn unary() {
    check_exact("unary.txt");
}

#[test]
fn binary() {
    check_exact("binary.txt");
}

#[test]
fn ternary() {
    check_exact("ternary.txt");
}

#[test]
fn int32() {
    check_exact("int32.txt");
}

#[test]
fn checked_index() {
    check_exact("index.txt");
}

#[test]
fn transcendental() {
    let mut failures = Vec::new();
    let mut inexact: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for row in rows("transcendental.txt") {
        let actual = evaluate(&row.name, &row.args);
        let distance = ulps(actual, row.expected);
        if distance == 0 {
            continue;
        }
        *inexact.entry(row.name.clone()).or_default() += 1;
        if distance > MAX_ULPS || EXACT_TRANSCENDENTALS.contains(&row.name.as_str()) {
            failures.push(format!(
                "transcendental.txt:{}: {}({:?}) = {actual:?}, V8 says {:?} ({distance} ulps)",
                row.line, row.name, row.args, row.expected
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches (inexact per function: {inexact:?}):\n{}",
        failures.len(),
        failures[..failures.len().min(60)].join("\n")
    );
}
